// And groups predicates with the AND operator between them.
func And(predicates ...predicate.TofuStateVersion) predicate.TofuStateVersion {
	return predicate.TofuStateVersion(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.TofuStateVersion) predicate.TofuStateVersion {
	return predicate.TofuStateVersion(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.TofuStateVersion) predicate.TofuStateVersion {
	return predicate.TofuStateVersion(sql.NotPredicates(p))
}
